// revenue-conversion-fix.js
// Brainstem directive: paidEvents still zero after many runs.
// This module hooks into checkout/offer flow to ensure conversion events are captured.

const axios = require('axios');

module.exports = async function captureConversionEvent(eventData) {
  // eventData: { userId, offerId, amount, currency, timestamp }
  try {
    // Simulate posting to internal revenue endpoint
    const response = await axios.post('http://localhost:4000/api/revenue/event', {
      type: 'conversion',
      ...eventData
    });
    return response.data;
  } catch (error) {
    console.error('Revenue conversion capture failed:', error.message);
    // Retry logic could be added here
    return null;
  }
};
